W=[E('null','/nʌl/','无效的；空值的','原来该起作用的东西，在这里不算数；技术语境也可表示没有值。','借法语 nul，接拉丁 nūllus“没有任何”。这不是把英语 no 和某个后缀拼起来。',N+[['法语 nul → 英语 null','先用于不具有效力，后扩展到数量及技术语境']],'a null agreement 是无效的协议；代码中的 null 则常用来表示“这里没有对象或值”。例如 JavaScript 的 null 是一个特定的空值，不是数字 0，也不是空字符串。两种语境都能联系“没有”，但具体规则不能混用。','null and void；a null value；return null。','zero 是数值零；null 常表示缺少值或对象。法律表达 null and void 中两个词加强同一意思：不具有效力。',('The agreement was declared null and void.','这份协议被宣布无效。'),('The function returns null when it cannot find a matching user.','找不到匹配用户时，这个函数返回 null。'),sources=['https://www.etymonline.com/word/null','https://en.wiktionary.org/wiki/null','https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Operators/null']),
E('nullify','/ˈnʌlɪfaɪ/','使无效；抵消','原本存在的效力或优势，被另一件事抹掉。','有后期拉丁 nullificāre 借入分析，组成是 nūllus 无 + facere 做、使；现代也常按 null + -ify“使成为”理解。',N+[['后期拉丁 nullificāre〔使归于无〕','由 nullus 与 facere 的组合形成'],['英语 nullify','使规则、决定或实际效果失去作用']],'它既能用于正式规则，也能用于生活中的效果：折扣省下的钱全被运费吃掉，运费就 nullifies the saving。重点不是事物消失，而是它产生的作用被抵消了。','nullify a decision；nullify an advantage；nullify the effect of something。','annul 常强调正式宣布无效；nullify 也能说没有正式程序的实际抵消。',('The extra delivery charge nullified the saving from the discount.','额外运费抵消了折扣省下的钱。'),('The court nullified the disputed decision.','法院宣布那项有争议的决定无效。'),sources=['https://www.etymonline.com/word/nullify','https://en.wiktionary.org/wiki/nullify','https://www.oxfordlearnersdictionaries.com/definition/english/nullify']),
E('nullification','/ˌnʌlɪfɪˈkeɪʃən/','使无效；废止；抵消','把“让它不再起作用”这件事作为一个名词来谈。','借后期拉丁 nullificātiō，接 nullificāre 使归于无。现代对应 nullify → nullification 的动名词变化，但历史名词本身有拉丁借入路线。',N+[['后期拉丁 nullificāre → nullificātiō','使归于无 → 这个行为或结果'],['英语 nullification','使某物失效；在政治与法律中也有专门用法']],'读到 the nullification of the result，就把它展开为“让这个结果失效”。比 cancellation 更正式，常用于评论一项结果、决定或规则如何被取消效力。历史上的政治专名用法，还要结合具体背景理解。','the nullification of an election result；the nullification of a decision。','nullity 偏向无效状态，nullification 偏向使它无效的行为或结果。',('The report called for the nullification of the disputed result.','报告呼吁宣布那个有争议的结果无效。'),('The novel ends with the nullification of the king’s decree.','小说以国王法令被废止而告终。'),sources=['https://www.etymonline.com/word/nullification','https://en.wiktionary.org/wiki/nullification']),
E('nullity','/ˈnʌləti/','无效；无足轻重的人或事物','一种是“没有效力”，另一种是带轻蔑意味的“算不上什么”。','经法语 nullité 或其中世纪拉丁来源 nūllitās，接 nūllus。现代能看出 null + -ity，但不是只能按英语内部派生解释。',N+[['中世纪拉丁 nūllitās → 法语 nullité','无效、虚无的状态'],['英语 nullity','无效；也指被认为没有价值或作用的人事']],'法律文字中 a nullity 可说某项行为根本不具有效力。评论家把作品叫 a nullity，则是在说它空洞、没有分量；这种评价很重，不是普通的“有点无聊”。','a legal nullity；the nullity of an agreement；dismiss something as a nullity。','nullity 说无效状态或被视为毫无分量的事物；nullification 说使某物无效这个过程。',('The judgment described the agreement as a legal nullity.','判决认定这份协议在法律上无效。'),('The critic dismissed the film as an artistic nullity.','评论家把这部电影贬为毫无艺术价值的空壳。'),sources=['https://en.wiktionary.org/wiki/nullity','https://www.merriam-webster.com/dictionary/nullity','https://www.etymonline.com/word/nullity']),
E('annul','/əˈnʌl/','宣布无效；撤销','用正式决定说：这件事不算数。','后期拉丁 annullāre 来自 ad- 向、使归于 + nullum 无；ad- 在 n 前同化成 an-。英语经法语借入，也有直接接拉丁的路线。',A,'被 annul 的常是婚姻、合同、决定或选举结果。它强调效力被正式否定，不只是把下一次安排取消。拼写 annulled、annulling 保留末尾双写的 l。','annul a marriage；annul a contract；annul an election result。','cancel 范围更广，可以取消预约；annul 常用于正式效力。annual“每年的”来自年，与这里的 null 无关。',('The court annulled the election result after reviewing the evidence.','法院审查证据后撤销了那次选举结果。'),('The story turns on a decision to annul the marriage.','故事围绕宣布那段婚姻无效的决定展开。'),sources=['https://www.etymonline.com/word/annul','https://en.wiktionary.org/wiki/annul']),
E('annulment','/əˈnʌlmənt/','宣告无效；婚姻无效的宣告','把正式否定效力这件事命名，最常见于婚姻语境。','现代是 annul + -ment。历史上中古英语既有由 annullen 派生的路线，也受到法语 annullement 的借入影响。',N+[['后期拉丁 annullāre → 法语 anuler／annuller','使归于无 → 宣布无效'],['并列路线：中古英语 annullen + -ment；法语 annullement 借入','形成英语 annulment'],['现代 annulment','宣告无效，常用于婚姻']],'它与 divorce 的视角不同：divorce 是结束婚姻，annulment 是对婚姻的有效性作出否定。读历史或小说时，抓住这个词义差别即可；具体法律效果要看相关制度。','seek an annulment；grant an annulment；the annulment of a marriage。','annul 是动作，annulment 是这个动作或决定的名称。它并不等于所有类型的分手。',('She sought an annulment of the marriage.','她申请宣告那段婚姻无效。'),('The biography explains the dispute over the annulment.','这本传记解释了围绕婚姻无效宣告产生的争议。'),sources=['https://www.etymonline.com/word/annulment','https://en.wiktionary.org/wiki/annulment','https://www.oxfordlearnersdictionaries.com/definition/english/annulment'])]
ROOT=dict(meaning='无；没有任何',core='从没有，走到不算数、没有效力。',image='不是把纸张撕掉，而是给上面的约定盖一个“无效”印章。',intro='拉丁 nūllus 的意思是“没有任何”。法律和日常抽象表达把它用来谈效力归零；计算机又借 null 表示缺少值或对象等特定状态。',forms='null 是借词；nullify 的 -ify 接使成为的构词传统。annul 中 an- 不是否定前缀，而是 ad- 的同化形式；真正的“无”在 null。',branches=[['状态与结果','null；nullity'],['让作用消失','nullify；nullification'],['正式宣布无效','annul；annulment']],contrasts='null 不自动等于数字 zero；annul 不来自 annual 的年。现代能拆分的词，也可能各自借入拉丁或法语形式。',practice='先分“无效的状态”和“让它无效的动作”，再选 null、nullity、nullify 或 annul。',sources=['https://www.etymonline.com/word/null','https://www.etymonline.com/word/annul','https://www.etymonline.com/word/nullification'])
